3	namespace App\Services\Shopify;
4	
5	use App\Exceptions\Shopify\ShopifyTransportException;
6	use App\Http\Controllers\Concerns\NormalizesShopDomain;
7	use App\Jobs\Shopify\CreateShopifyMetafieldsJob;
8	use App\Jobs\Shopify\CreateShopifySalesChannelJob;
9	use App\Jobs\Shopify\CreateStorefrontAccessTokenJob;
10	use App\Jobs\Shopify\RegisterShopifyWebhooksJob;
11	use App\Jobs\Shopify\SyncShopifyBrandDesignJob;
12	use App\Models\Core\Professional\BrandProfile;
13	use App\Models\Core\Professional\Professional;
14	use App\Models\Core\Professional\ProfessionalIntegration;
15	use App\Models\Core\Site\Site;
16	use App\Services\Cache\ProfessionalCacheService;
17	use App\Services\Shopify\Client\ShopifyAdminClient;
18	use Illuminate\Support\Arr;
19	use Illuminate\Support\Facades\Log;
20	
21	// V2: Handles Shopify reinstalls and existing-account connects. Fresh installs are deferred to the setup wizard via bootstrap.
22	class BrandSignupService
23	{
24	    use NormalizesShopDomain;
25	
26	    public function __construct(
27	        private readonly ShopProfileAutoFillService $autoFill,
28	        private readonly ShopifyAdminClient $shopifyClient,
29	    ) {}
30	
31	    public function handleReinstall(
32	        ProfessionalIntegration $integration,
33	        string $accessToken,
34	        array $shopData,
35	        array $scopes,
36	    ): BrandSignupResult {
37	        $metadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
38	
39	        // Revoke the old storefront token at Shopify before issuing a new one.
40	        // A leaked storefront token otherwise survives indefinitely after reinstall.
41	        if ($integration->storefront_token !== null) {
42	            $this->revokeStorefrontToken($metadata, (string) $integration->access_token);
43	            $integration->update(['storefront_token' => null]);
44	        }
45	
46	        $integration->update([
47	            'access_token' => $accessToken,
48	            'provider_metadata' => array_merge($metadata, [
49	                'scopes' => $scopes,
50	                'connected_at' => now()->toIso8601String(),
51	                'webhook_registration_state' => 'queued',
52	            ]),
53	        ]);
54	
55	        $this->dispatchInstallJobs((string) $integration->id);
56	
57	        $professional = Professional::findOrFail($integration->professional_id);
58	        $site = Site::where('professional_id', $professional->id)->firstOrFail();
59	        $brandProfile = BrandProfile::where('professional_id', $professional->id)->first();
60	
61	        Log::info('Shopify brand reinstall', [
62	            'professional_id' => (string) $professional->id,
63	            'shop_domain' => Arr::get($metadata, 'shop_domain'),
64	        ]);
65	
66	        return new BrandSignupResult(
67	            professional: $professional,
68	            site: $site,
69	            brandProfile: $brandProfile,
70	            integration: $integration,
71	            isReinstall: true,
72	        );
73	    }
74	
75	    public function handleExistingBrandConnect(
76	        Professional $professional,
77	        string $shopDomain,
78	        string $accessToken,
79	        array $shopData,
80	        array $scopes,
81	    ): BrandSignupResult {
82	        $shopId = trim((string) Arr::get($shopData, 'id', ''));
83	        $shopCurrency = strtoupper(trim((string) Arr::get($shopData, 'currency', '')));
84	
85	        $integration = ProfessionalIntegration::updateOrCreate(
86	            [
87	                'professional_id' => (string) $professional->id,
88	                'provider' => ProfessionalIntegration::PROVIDER_SHOPIFY,
89	            ],
90	            [
91	                'external_account_id' => $shopDomain,
92	                'access_token' => $accessToken,
93	                'provider_metadata' => [
94	                    'shop_domain' => $shopDomain,
95	                    'shop_id' => $shopId !== '' ? "gid://shopify/Shop/{$shopId}" : null,
96	                    'shop_currency' => $shopCurrency !== '' ? $shopCurrency : null,
97	                    'scopes' => $scopes,
98	                    'webhook_orders_topic' => config('services.shopify.webhook_orders_topic', 'orders/paid'),
99	                    'connected_at' => now()->toIso8601String(),
100	                    'webhook_registration_state' => 'queued',
101	                ],
102	            ]
103	        );
104	
105	        BrandProfile::firstOrCreate(
106	            ['professional_id' => (string) $professional->id],
107	            ['setup_complete' => false]
108	        );
109	
110	        $site = Site::where('professional_id', $professional->id)->first();
111	        $brandProfile = BrandProfile::where('professional_id', $professional->id)->first();
112	
113	        if ($site) {
114	            $this->autoFill->fillFromShopData($professional, $site, $brandProfile, $shopData);
115	        }
116	
117	        app(ProfessionalCacheService::class)->invalidateProfessional($professional);
118	
119	        $this->dispatchInstallJobs((string) $integration->id);
120	
121	        Log::info('Shopify brand connect (existing account)', [
122	            'professional_id' => (string) $professional->id,
123	            'shop_domain' => $shopDomain,
124	        ]);
125	
126	        return new BrandSignupResult(
127	            professional: $professional,
128	            site: $site,
129	            brandProfile: $brandProfile,
130	            integration: $integration,
131	            isReinstall: false,
132	        );
133	    }
134	
135	    /**
136	     * Delete this app's storefront access token from Shopify.
137	     * Best-effort: any failure is logged and swallowed so the reinstall continues.
138	     */
139	    private function revokeStorefrontToken(array $metadata, string $oldAccessToken): void
140	    {
141	        $shopDomain = trim((string) Arr::get($metadata, 'shop_domain', ''));
142	        if ($shopDomain === '' || $oldAccessToken === '') {
143	            return;
144	        }
145	
146	        $apiVersion = trim((string) config('services.shopify.api_version', '2025-01'));
147	
148	        try {
149	            $response = $this->shopifyClient->rest(
150	                method: 'GET',
151	                shopDomain: $shopDomain,
152	                accessToken: $oldAccessToken,
153	                path: "/admin/api/{$apiVersion}/storefront_access_tokens.json",
154	                timeoutSeconds: 15,
155	            );
156	        } catch (ShopifyTransportException $e) {
157	            Log::warning('Shopify reinstall: could not list storefront tokens for revocation', [
158	                'shop_domain' => $shopDomain,
159	                'status' => $e->status,
160	            ]);
161	
162	            return;
163	        }
164	
165	        $tokens = $response->json('storefront_access_tokens', []);
166	        if (! is_array($tokens)) {
167	            return;
168	        }
169	
170	        foreach ($tokens as $token) {
171	            $title = (string) ($token['title'] ?? '');
172	            if ($title !== 'Side St' && $title !== 'Side St Hydrogen') {
173	                continue;
174	            }
175	
176	            $id = (string) ($token['id'] ?? '');
177	            if ($id === '') {
178	                continue;
179	            }
180	
181	            try {
182	                $this->shopifyClient->rest(
183	                    method: 'DELETE',
184	                    shopDomain: $shopDomain,
185	                    accessToken: $oldAccessToken,
186	                    path: "/admin/api/{$apiVersion}/storefront_access_tokens/{$id}.json",
187	                    timeoutSeconds: 15,
188	                );
189	            } catch (ShopifyTransportException $e) {
190	                // 404 = already gone, any other status = best-effort failure — both are acceptable.
191	                Log::warning('Shopify reinstall: storefront token revocation failed', [
192	                    'shop_domain' => $shopDomain,
193	                    'token_id' => $id,
194	                    'status' => $e->status,
195	                ]);
196	            }
197	        }
198	    }
199	
200	    public function dispatchInstallJobs(string $integrationId): void
201	    {
202	        $jobs = [
203	            RegisterShopifyWebhooksJob::class,
204	            CreateStorefrontAccessTokenJob::class,
205	            CreateShopifyMetafieldsJob::class,
206	            CreateShopifySalesChannelJob::class,
207	            // Unified brand-design sync: logos, colours, enums, slogan in one job.
208	            SyncShopifyBrandDesignJob::class,
209	        ];
210	
211	        foreach ($jobs as $jobClass) {
212	            try {
213	                $jobClass::dispatch($integrationId);
214	            } catch (\Throwable $e) {
215	                Log::warning('Failed to dispatch Shopify install job', [
216	                    'integration_id' => $integrationId,
217	                    'job' => class_basename($jobClass),
218	                    'message' => $e->getMessage(),
219	                ]);
220	            }
221	        }
222	    }
223	}
