3	namespace App\Models\Core\Professional;
4	
5	use App\Models\BaseModel;
6	use Illuminate\Database\Eloquent\Concerns\HasUuids;
7	use Illuminate\Database\Eloquent\Relations\BelongsTo;
8	
9	// V2: OAuth integration record (Square, Fresha, Shopify). Stores encrypted tokens and provider_metadata (webhook IDs, collection handles, etc.).
10	class ProfessionalIntegration extends BaseModel
11	{
12	    use HasUuids;
13	
14	    public const PROVIDER_SQUARE = 'square';
15	
16	    public const PROVIDER_FRESHA = 'fresha';
17	
18	    public const PROVIDER_SHOPIFY = 'shopify';
19	
20	    protected $table = 'core.professional_integrations';
21	
22	    public $incrementing = false;
23	
24	    protected $keyType = 'string';
25	
26	    protected $hidden = [
27	        'access_token',
28	        'refresh_token',
29	        'storefront_token',
30	        'provider_metadata',
31	    ];
32	
33	    protected $fillable = [
34	        'professional_id',
35	        'provider',
36	        'external_account_id',
37	        'access_token',
38	        'refresh_token',
39	        'storefront_token',
40	        'expires_at',
41	        'catalog_latest_time',
42	        'last_catalog_sync_at',
43	        'last_catalog_sync_error',
44	        'provider_metadata',
45	    ];
46	
47	    protected $casts = [
48	        'access_token' => 'encrypted',
49	        'refresh_token' => 'encrypted',
50	        'storefront_token' => 'encrypted',
51	        'expires_at' => 'datetime',
52	        'catalog_latest_time' => 'datetime',
53	        'last_catalog_sync_at' => 'datetime',
54	        'provider_metadata' => 'array',
55	    ];
56	
57	    public function professional(): BelongsTo
58	    {
59	        return $this->belongsTo(Professional::class, 'professional_id');
60	    }
61	
62	    public function scopeProvider($query, string $provider)
63	    {
64	        return $query->where('provider', mb_strtolower(trim($provider)));
65	    }
66	
67	    /**
68	     * Atomically merge keys into provider_metadata without overwriting
69	     * keys written by other concurrent jobs.
70	     *
71	     * Production (pgsql): uses the jsonb `||` merge operator so the update
72	     * is a single atomic statement even under concurrent writes from
73	     * webhooks / onboarding jobs / storefront token creation.
74	     *
75	     * Tests (sqlite, via the pgsql→sqlite redirect in TestCase): falls back
76	     * to a refresh + PHP-side array merge + save. Loss of atomicity is
77	     * acceptable because the test suite is single-process.
78	     */
79	    public function mergeProviderMetadata(array $data): void
80	    {
81	        $connection = $this->getConnection();
82	
83	        if ($connection->getDriverName() === 'pgsql') {
84	            $json = json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
85	
86	            $connection->update(
87	                "UPDATE {$this->getTable()} SET provider_metadata = COALESCE(provider_metadata, '{}'::jsonb) || ?::jsonb, updated_at = ? WHERE id = ?",
88	                [$json, now(), $this->id]
89	            );
90	
91	            $this->refresh();
92	
93	            return;
94	        }
95	
96	        // SQLite fallback: non-atomic but safe in single-process test runs.
97	        $this->refresh();
98	        $current = is_array($this->provider_metadata) ? $this->provider_metadata : [];
99	        $this->provider_metadata = array_merge($current, $data);
100	        $this->save();
101	    }
102	}
