95	    public function handle(ShopifyAdminClient $client): void
96	    {
97	        $this->client = $client;
98	        $integration = ProfessionalIntegration::query()
99	            ->where('id', $this->integrationId)
100	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
101	            ->first();
102	
103	        if (! $integration) {
104	            return;
105	        }
106	
107	        $metadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
108	        $shopDomain = trim((string) Arr::get($metadata, 'shop_domain', ''));
109	        $accessToken = trim((string) $integration->access_token);
110	
111	        if ($shopDomain === '' || $accessToken === '' || ! preg_match('/^[a-z0-9\-]+\.myshopify\.com$/', $shopDomain)) {
112	            $integration->mergeProviderMetadata([
113	                'webhooks_state' => 'failed',
114	                'webhooks_error' => 'Missing or invalid shop domain or access token.',
115	            ]);
116	
117	            return;
118	        }
119	
120	        $apiVersion = trim((string) config('services.shopify.api_version', '2025-01'));
121	        $baseUrl = rtrim((string) config('app.url'), '/');
122	        $results = [];
123	        $allSucceeded = true;
124	
125	        foreach (self::WEBHOOKS as $topic => $path) {
126	            $callbackUrl = $baseUrl.$path;
127	
128	            try {
129	                $existing = $this->findExistingWebhook($shopDomain, $accessToken, $apiVersion, $topic, $callbackUrl);
130	
131	                if ($existing) {
132	                    $results[$topic] = ['state' => 'registered', 'webhook_id' => $existing, 'existed' => true];
133	
134	                    continue;
135	                }
136	
137	                $webhookId = $this->createWebhook($shopDomain, $accessToken, $apiVersion, $topic, $callbackUrl);
138	                $results[$topic] = ['state' => 'registered', 'webhook_id' => $webhookId, 'existed' => false];
139	            } catch (\RuntimeException $e) {
140	                // Covers ShopifyClientException (transport/throttle/GraphQL errors) and RuntimeException
141	                // thrown by createWebhook (userErrors, missing ID). Anything else propagates and fails the job immediately.
142	                Log::error('Failed to register Shopify webhook.', [
143	                    'integration_id' => $this->integrationId,
144	                    'shop_domain' => $shopDomain,
145	                    'topic' => $topic,
146	                    'error' => $e->getMessage(),
147	                ]);
148	
149	                $results[$topic] = ['state' => 'failed', 'error' => $e->getMessage()];
150	                $allSucceeded = false;
151	            }
152	        }
153	
154	        $integration->mergeProviderMetadata([
155	            'webhooks_state' => $allSucceeded ? 'registered' : 'partial',
156	            'webhooks_registered_at' => now()->toIso8601String(),
157	            'webhooks_results' => $results,
158	            // Backward-compat keys
159	            'webhook_registration_state' => $allSucceeded ? 'registered' : 'partial',
160	            'webhook_registration_last_attempt_at' => now()->toIso8601String(),
161	        ]);
162	
163	        Log::info('Shopify webhook registration complete.', [
164	            'integration_id' => $this->integrationId,
165	            'shop_domain' => $shopDomain,
166	            'all_succeeded' => $allSucceeded,
167	            'topics_registered' => collect($results)->where('state', 'registered')->count(),
168	            'topics_failed' => collect($results)->where('state', 'failed')->count(),
169	        ]);
170	
171	        // Throw to trigger job retry when any topic failed. Already-registered webhooks are
172	        // idempotent (findExistingWebhook skips them), so retries only re-attempt failed topics.
173	        if (! $allSucceeded) {
174	            $failedTopics = implode(', ', array_keys(array_filter($results, fn ($r) => $r['state'] === 'failed')));
175	            throw new \RuntimeException("Shopify webhook registration incomplete for {$shopDomain}: failed topics: {$failedTopics}");
176	        }
177	    }
