179	    private function findExistingWebhook(string $shopDomain, string $accessToken, string $apiVersion, string $topic, string $callbackUrl): ?string
180	    {
181	        $data = $this->queryShopify($shopDomain, $accessToken, $apiVersion, self::WEBHOOK_SUBSCRIPTIONS_QUERY, [
182	            'topic' => $topic,
183	            'first' => 10,
184	        ]);
185	
186	        $edges = Arr::get($data, 'webhookSubscriptions.edges', []);
187	        if (! is_array($edges)) {
188	            return null;
189	        }
190	
191	        foreach ($edges as $edge) {
192	            $node = $edge['node'] ?? null;
193	            if (! is_array($node)) {
194	                continue;
195	            }
196	
197	            $existingUrl = trim((string) Arr::get($node, 'endpoint.callbackUrl', ''));
198	            if (strcasecmp($existingUrl, $callbackUrl) === 0) {
199	                return (string) $node['id'];
200	            }
201	        }
202	
203	        return null;
204	    }
205	
206	    private function createWebhook(string $shopDomain, string $accessToken, string $apiVersion, string $topic, string $callbackUrl): string
207	    {
208	        $data = $this->queryShopify($shopDomain, $accessToken, $apiVersion, self::WEBHOOK_SUBSCRIPTION_CREATE, [
209	            'topic' => $topic,
210	            'webhookSubscription' => [
211	                'callbackUrl' => $callbackUrl,
212	                'format' => 'JSON',
213	            ],
214	        ]);
215	
216	        $userErrors = Arr::get($data, 'webhookSubscriptionCreate.userErrors', []);
217	        if (is_array($userErrors) && $userErrors !== []) {
218	            $message = (string) Arr::get($userErrors, '0.message', 'Unknown webhook creation error.');
219	            throw new \RuntimeException("Shopify webhook creation failed for {$topic}: {$message}");
220	        }
221	
222	        $webhookId = Arr::get($data, 'webhookSubscriptionCreate.webhookSubscription.id');
223	        if (! $webhookId) {
224	            throw new \RuntimeException("Shopify webhook was created for {$topic} but no ID was returned.");
225	        }
226	
227	        return (string) $webhookId;
228	    }
