85	        $integration = ProfessionalIntegration::updateOrCreate(
86	            [
87	                'professional_id' => (string) $professional->id,
88	                'provider' => ProfessionalIntegration::PROVIDER_SHOPIFY,
89	            ],
90	            [
91	                'external_account_id' => $shopDomain,
92	                'access_token' => $accessToken,
93	                'provider_metadata' => [
94	                    'shop_domain' => $shopDomain,
95	                    'shop_id' => $shopId !== '' ? "gid://shopify/Shop/{$shopId}" : null,
96	                    'shop_currency' => $shopCurrency !== '' ? $shopCurrency : null,
97	                    'scopes' => $scopes,
98	                    'webhook_orders_topic' => config('services.shopify.webhook_orders_topic', 'orders/paid'),
99	                    'connected_at' => now()->toIso8601String(),
100	                    'webhook_registration_state' => 'queued',
101	                ],
102	            ]
103	        );
104	
105	        BrandProfile::firstOrCreate(
106	            ['professional_id' => (string) $professional->id],
107	            ['setup_complete' => false]
108	        );
109	
110	        $site = Site::where('professional_id', $professional->id)->first();
111	        $brandProfile = BrandProfile::where('professional_id', $professional->id)->first();
112	
113	        if ($site) {
