133	    }
134	
135	    /**
136	     * Delete this app's storefront access token from Shopify.
137	     * Best-effort: any failure is logged and swallowed so the reinstall continues.
138	     */
139	    private function revokeStorefrontToken(array $metadata, string $oldAccessToken): void
140	    {
141	        $shopDomain = trim((string) Arr::get($metadata, 'shop_domain', ''));
142	        if ($shopDomain === '' || $oldAccessToken === '') {
143	            return;
144	        }
145	
146	        $apiVersion = trim((string) config('services.shopify.api_version', '2025-01'));
147	
148	        try {
149	            $response = $this->shopifyClient->rest(
150	                method: 'GET',
151	                shopDomain: $shopDomain,
152	                accessToken: $oldAccessToken,
153	                path: "/admin/api/{$apiVersion}/storefront_access_tokens.json",
154	                timeoutSeconds: 15,
155	            );
156	        } catch (ShopifyTransportException $e) {
157	            Log::warning('Shopify reinstall: could not list storefront tokens for revocation', [
158	                'shop_domain' => $shopDomain,
159	                'status' => $e->status,
160	            ]);
161	
162	            return;
163	        }
164	
165	        $tokens = $response->json('storefront_access_tokens', []);
166	        if (! is_array($tokens)) {
167	            return;
168	        }
169	
170	        foreach ($tokens as $token) {
171	            $title = (string) ($token['title'] ?? '');
172	            if ($title !== 'Side St' && $title !== 'Side St Hydrogen') {
173	                continue;
174	            }
175	
176	            $id = (string) ($token['id'] ?? '');
177	            if ($id === '') {
178	                continue;
179	            }
180	
181	            try {
182	                $this->shopifyClient->rest(
183	                    method: 'DELETE',
184	                    shopDomain: $shopDomain,
185	                    accessToken: $oldAccessToken,
186	                    path: "/admin/api/{$apiVersion}/storefront_access_tokens/{$id}.json",
187	                    timeoutSeconds: 15,
188	                );
189	            } catch (ShopifyTransportException $e) {
190	                // 404 = already gone, any other status = best-effort failure — both are acceptable.
191	                Log::warning('Shopify reinstall: storefront token revocation failed', [
192	                    'shop_domain' => $shopDomain,
193	                    'token_id' => $id,
194	                    'status' => $e->status,
195	                ]);
196	            }
197	        }
198	    }
199	
200	    public function dispatchInstallJobs(string $integrationId): void
201	    {
202	        $jobs = [
203	            RegisterShopifyWebhooksJob::class,
204	            CreateStorefrontAccessTokenJob::class,
205	            CreateShopifyMetafieldsJob::class,
206	            CreateShopifySalesChannelJob::class,
207	            // Unified brand-design sync: logos, colours, enums, slogan in one job.
208	            SyncShopifyBrandDesignJob::class,
209	        ];
210	
211	        foreach ($jobs as $jobClass) {
212	            try {
213	                $jobClass::dispatch($integrationId);
214	            } catch (\Throwable $e) {
215	                Log::warning('Failed to dispatch Shopify install job', [
216	                    'integration_id' => $integrationId,
217	                    'job' => class_basename($jobClass),
218	                    'message' => $e->getMessage(),
219	                ]);
220	            }
221	        }
222	    }
223	}
