37	    private const STOREFRONT_TOKEN_CREATE = <<<'GRAPHQL'
38	    mutation storefrontAccessTokenCreate($input: StorefrontAccessTokenInput!) {
39	      storefrontAccessTokenCreate(input: $input) {
40	        storefrontAccessToken {
41	          accessToken
42	          title
43	          id
44	        }
45	        userErrors {
46	          field
47	          message
48	        }
49	      }
50	    }
