52	
53	    // storefrontAccessTokens query was removed from GraphQL Admin API in 2025-01.
54	    // Use REST API to check for existing tokens.
55	    private const STOREFRONT_TOKENS_REST_PATH = '/admin/api/%s/storefront_access_tokens.json';
56	
57	    /** Populated by handle() — not serialized. */
58	    private ShopifyAdminClient $client;
59	
60	    public function __construct(public string $integrationId)
61	    {
62	        $this->onQueue('integrations');
63	    }
64	
65	    public function handle(ShopifyAdminClient $client): void
66	    {
67	        $this->client = $client;
68	        $integration = ProfessionalIntegration::query()
69	            ->where('id', $this->integrationId)
70	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
71	            ->first();
72	
73	        if (! $integration) {
74	            return;
75	        }
76	
77	        $metadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
78	        $shopDomain = trim((string) Arr::get($metadata, 'shop_domain', ''));
79	        $accessToken = trim((string) $integration->access_token);
80	
81	        if ($shopDomain === '' || $accessToken === '' || ! preg_match('/^[a-z0-9\-]+\.myshopify\.com$/', $shopDomain)) {
82	            return;
83	        }
84	
85	        // Token already provisioned — nothing to do.
86	        if ($integration->storefront_token !== null && trim((string) $integration->storefront_token) !== '') {
87	            return;
88	        }
89	
90	        $apiVersion = trim((string) config('services.shopify.api_version', '2025-01'));
91	
92	        try {
93	            // Check if a Side St token already exists in Shopify (e.g. from a previous run).
94	            $existing = $this->findExistingToken($shopDomain, $accessToken, $apiVersion);
95	            if ($existing) {
96	                $integration->update(['storefront_token' => $existing]);
97	
98	                return;
99	            }
100	
101	            // Create a new one.
102	            $token = $this->createToken($shopDomain, $accessToken, $apiVersion);
103	            $integration->update(['storefront_token' => $token]);
104	
105	            Log::info('Shopify Storefront API token created.', [
106	                'integration_id' => $this->integrationId,
107	                'shop_domain' => $shopDomain,
108	            ]);
109	        } catch (\Throwable $e) {
110	            Log::error('Failed to create Shopify Storefront API token.', [
111	                'integration_id' => $this->integrationId,
112	                'shop_domain' => $shopDomain,
113	                'error' => $e->getMessage(),
114	            ]);
