123	            'integration_id' => $this->integrationId,
124	            'error' => $e->getMessage(),
125	        ]);
126	    }
127	
128	    private function findExistingToken(string $shopDomain, string $accessToken, string $apiVersion): ?string
129	    {
130	        try {
131	            $response = $this->client->rest(
132	                method: 'GET',
133	                shopDomain: $shopDomain,
134	                accessToken: $accessToken,
135	                path: sprintf(self::STOREFRONT_TOKENS_REST_PATH, $apiVersion),
136	            );
137	        } catch (\App\Exceptions\Shopify\ShopifyTransportException $e) {
138	            return null;
139	        }
