141	        $tokens = $response->json('storefront_access_tokens', []);
142	
143	        foreach ($tokens as $token) {
144	            $title = (string) ($token['title'] ?? '');
145	            if ($title === 'Side St' || $title === 'Side St Hydrogen') {
146	                return (string) ($token['access_token'] ?? '');
147	            }
148	        }
