153	    private function createToken(string $shopDomain, string $accessToken, string $apiVersion): string
154	    {
155	        $data = $this->queryShopify($shopDomain, $accessToken, $apiVersion, self::STOREFRONT_TOKEN_CREATE, [
156	            'input' => ['title' => 'Side St Hydrogen'],
157	        ]);
158	
159	        $userErrors = Arr::get($data, 'storefrontAccessTokenCreate.userErrors', []);
160	        if (is_array($userErrors) && $userErrors !== []) {
161	            $message = (string) Arr::get($userErrors, '0.message', 'Unknown error.');
162	            throw new \RuntimeException("Storefront token creation failed: {$message}");
163	        }
164	
165	        $token = Arr::get($data, 'storefrontAccessTokenCreate.storefrontAccessToken.accessToken');
166	        if (! $token) {
167	            throw new \RuntimeException('Storefront token created but no token value returned.');
168	        }
169	
170	        return (string) $token;
171	    }
