173	    private function queryShopify(string $shopDomain, string $accessToken, string $apiVersion, string $query, array $variables = []): array
174	    {
175	        $response = $this->client->graphql(
176	            $shopDomain,
177	            $accessToken,
178	            $apiVersion,
179	            $query,
180	            $variables,
181	        );
182	
183	        return is_array($response->json('data')) ? $response->json('data') : [];
184	    }
