167	    public function handle(ShopifyAdminClient $client): void
168	    {
169	        $this->client = $client;
170	        $integration = ProfessionalIntegration::query()
171	            ->where('id', $this->integrationId)
172	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
173	            ->first();
