175	        if (! $integration) {
176	            return;
177	        }
178	
179	        $metadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
180	        $shopDomain = trim((string) Arr::get($metadata, 'shop_domain', ''));
181	        $accessToken = trim((string) $integration->access_token);
182	        $apiVersion = trim((string) config('services.shopify.api_version', '2025-01'));
183	
184	        if ($shopDomain === '' || $accessToken === '' || ! preg_match('/^[a-z0-9\-]+\.myshopify\.com$/', $shopDomain)) {
185	            $integration->mergeProviderMetadata(['metafield_definitions_state' => 'failed']);
186	
187	            return;
188	        }
189	
190	        try {
191	            $existingProduct = $this->getExistingDefinitions($shopDomain, $accessToken, $apiVersion, 'PRODUCT');
192	            $existingShop = $this->getExistingDefinitions($shopDomain, $accessToken, $apiVersion, 'SHOP');
193	            $existingProductKeys = array_column($existingProduct, 'key');
194	            $existingShopKeys = array_column($existingShop, 'key');
195	
196	            // Create product-level definitions. Two mismatches can force a
197	            // delete + recreate on existing definitions:
198	            //   1. useAsCollectionCondition missing but required (existing case)
199	            //   2. storefront access differs from desired (e.g. affiliate_discount_pct
200	            //      flipped from [] to PUBLIC_READ so Hydrogen can read it) — Shopify
201	            //      does not allow mutating `access` on an existing definition.
202	            // deleteAllAssociatedMetafields defaults to false on deletion, so any
203	            // existing metafield values on products survive the re-registration.
204	            foreach (self::PRODUCT_DEFINITIONS as $def) {
205	                $needsCollectionCondition = in_array($def['key'], self::COLLECTION_CONDITION_KEYS, true);
