211	                    $collectionConditionMismatch = $needsCollectionCondition
212	                        && $existing
213	                        && ! $existing['useAsCollectionCondition'];
214	
215	                    $accessMismatch = $existing
216	                        && ! $this->storefrontAccessMatches($existing['storefrontAccess'] ?? null, $desiredStorefrontAccess);
