218	                    if ($collectionConditionMismatch || $accessMismatch) {
219	                        Log::info('Deleting metafield definition to recreate with updated config', [
220	                            'key' => $def['key'],
221	                            'id' => $existing['id'],
222	                            'reason_collection_condition' => $collectionConditionMismatch,
223	                            'reason_access' => $accessMismatch,
224	                        ]);
