282	    /**
283	     * @return array<int, array{id: string, key: string, useAsCollectionCondition: bool}>
284	     */
285	    private function getExistingDefinitions(string $shopDomain, string $accessToken, string $apiVersion, string $ownerType): array
286	    {
287	        $response = $this->graphql($shopDomain, $accessToken, $apiVersion, self::METAFIELD_DEFINITIONS_QUERY, [
288	            'ownerType' => $ownerType,
289	            'namespace' => 'sidest',
290	            'first' => 50,
291	        ]);
292	
293	        $edges = $response->json('data.metafieldDefinitions.edges', []);
294	
295	        return array_map(
296	            static fn (array $edge): array => [
297	                'id' => (string) Arr::get($edge, 'node.id', ''),
298	                'key' => (string) Arr::get($edge, 'node.key', ''),
299	                'useAsCollectionCondition' => (bool) Arr::get($edge, 'node.useAsCollectionCondition', false),
300	                // null when the definition has no storefront access (Shopify returns
301	                // the access object but the `storefront` field is omitted in that
302	                // case); otherwise a string like "PUBLIC_READ".
303	                'storefrontAccess' => Arr::get($edge, 'node.access.storefront'),
304	            ],
305	            is_array($edges) ? $edges : []
306	        );
307	    }
308	
309	    /**
310	     * True when the storefront access on an existing definition already matches
311	     * what we want. Shopify normalises missing access to null and we store
312	     * absence the same way (no 'access' key in our definition array).
313	     */
314	    private function storefrontAccessMatches(?string $existing, ?string $desired): bool
315	    {
316	        return ($existing === null ? null : (string) $existing) === ($desired === null ? null : (string) $desired);
317	    }
318	
319	    private function createDefinition(string $shopDomain, string $accessToken, string $apiVersion, string $ownerType, array $def, bool $useAsCollectionCondition = false): void
320	    {
321	        $definition = [
322	            'namespace' => 'sidest',
323	            'key' => $def['key'],
324	            'name' => $def['name'],
325	            'type' => $def['type'],
326	            'description' => $def['description'],
327	            'ownerType' => $ownerType,
328	        ];
329	
330	        if (! empty($def['access'])) {
331	            $definition['access'] = $def['access'];
332	        }
333	
334	        if ($useAsCollectionCondition) {
335	            $definition['useAsCollectionCondition'] = true;
336	        }
337	
338	        $response = $this->graphql($shopDomain, $accessToken, $apiVersion, self::METAFIELD_DEFINITION_CREATE, [
339	            'definition' => $definition,
340	        ]);
341	
342	        $userErrors = $response->json('data.metafieldDefinitionCreate.userErrors', []);
343	        if (! empty($userErrors)) {
344	            Log::warning('Shopify metafield definition creation had errors', [
345	                'key' => $def['key'],
346	                'owner_type' => $ownerType,
347	                'use_as_collection_condition' => $useAsCollectionCondition,
348	                'errors' => $userErrors,
349	            ]);
350	        } else {
351	            $created = $response->json('data.metafieldDefinitionCreate.createdDefinition');
352	            Log::info('Shopify metafield definition created', [
353	                'key' => $def['key'],
354	                'owner_type' => $ownerType,
355	                'id' => $created['id'] ?? null,
356	                'useAsCollectionCondition' => $created['useAsCollectionCondition'] ?? null,
357	            ]);
358	        }
359	    }
360	
361	    private function deleteDefinition(string $shopDomain, string $accessToken, string $apiVersion, string $definitionId): void
362	    {
363	        $response = $this->graphql($shopDomain, $accessToken, $apiVersion, self::METAFIELD_DEFINITION_DELETE, [
364	            'id' => $definitionId,
365	            'deleteAllAssociatedMetafields' => false,
366	        ]);
367	
368	        $userErrors = $response->json('data.metafieldDefinitionDelete.userErrors', []);
369	        if (! empty($userErrors)) {
370	            Log::warning('Failed to delete metafield definition', [
371	                'definition_id' => $definitionId,
372	                'errors' => $userErrors,
373	            ]);
374	        }
375	    }
376	
377	    private function graphql(string $shopDomain, string $accessToken, string $apiVersion, string $query, array $variables): \Illuminate\Http\Client\Response
378	    {
379	        return $this->client->graphql(
380	            $shopDomain,
381	            $accessToken,
382	            $apiVersion,
383	            $query,
384	            $variables,
385	            $this->timeout,
386	        );
387	    }
388	}
