3	namespace App\Jobs\Shopify;
4	
5	use App\Models\Core\Professional\ProfessionalIntegration;
6	use App\Models\Core\Site\Site;
7	use App\Services\Cache\SiteCacheService;
8	use App\Services\Media\BrandDesignMediaService;
9	use App\Services\Shopify\BrandDesignImporter;
10	use Illuminate\Bus\Queueable;
11	use Illuminate\Contracts\Queue\ShouldBeUnique;
12	use Illuminate\Contracts\Queue\ShouldQueue;
13	use Illuminate\Foundation\Bus\Dispatchable;
14	use Illuminate\Queue\InteractsWithQueue;
15	use Illuminate\Queue\SerializesModels;
16	use Illuminate\Support\Arr;
17	use Illuminate\Support\Facades\Http;
18	use Illuminate\Support\Facades\Log;
19	
20	// Unified brand-design importer. Replaces the old pair of
21	// SyncShopifyThemeTokensJob + SyncShopifyBrandLogoJob.
22	//
23	// What it does, per invocation:
24	//   1. Pulls the brand-design shape from Shopify via BrandDesignImporter
25	//      (Brand API for colours/logos/slogan; active theme's settings_data.json
26	//      for radius/border/spacing enums).
27	//   2. Downloads logo files from the Shopify CDN into our own media disk so
28	//      the URLs we persist are stable when Shopify's CDN tokens rotate.
29	//   3. Merges the new shape into site.settings.design using overwrite-if-present,
30	//      leave-if-absent semantics — a missing Shopify value never nulls a
31	//      user's existing edit.
32	//   4. Writes a `sidest.brand_design` shop metafield so other Sidest surfaces
33	//      (and debugging tools) can read the same shape from Shopify directly.
34	//   5. Busts the brand-design cache Hydrogen reads from.
35	class SyncShopifyBrandDesignJob implements ShouldBeUnique, ShouldQueue
36	{
37	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
38	
39	    public int $tries = 3;
40	
41	    public int $timeout = 120;
42	
43	    // Worst-case execution = tries * timeout = 360s. Hold the unique lock
44	    // longer than that so a stuck-then-retried run can never race another
45	    // copy of itself against the same site.settings.design write.
46	    public int $uniqueFor = 600;
47	
48	    private const METAFIELDS_SET_MUTATION = <<<'GRAPHQL'
49	    mutation metafieldsSet($metafields: [MetafieldsSetInput!]!) {
50	      metafieldsSet(metafields: $metafields) {
51	        metafields { id key }
52	        userErrors { field message code }
53	      }
54	    }
55	    GRAPHQL;
56	
57	    public function __construct(
58	        public string $integrationId,
59	    ) {
60	        $this->onQueue('integrations');
61	    }
62	
63	    public function uniqueId(): string
64	    {
65	        return $this->integrationId;
66	    }
67	
68	    public function backoff(): array
69	    {
70	        return [10, 30, 60];
71	    }
72	
73	    public function handle(BrandDesignImporter $importer, BrandDesignMediaService $brandDesign): void
74	    {
75	        $integration = ProfessionalIntegration::query()
76	            ->where('id', $this->integrationId)
77	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
78	            ->first();
79	
80	        if (! $integration) {
81	            return;
82	        }
83	
84	        $site = Site::where('professional_id', $integration->professional_id)->first();
85	
86	        if (! $site) {
87	            Log::warning('Brand design sync skipped — no site for professional.', [
88	                'integration_id' => $this->integrationId,
89	                'professional_id' => (string) $integration->professional_id,
90	            ]);
91	
92	            return;
93	        }
94	
95	        try {
96	            $imported = $importer->import($integration);
97	        } catch (\Throwable $e) {
98	            Log::warning('Brand design import failed.', [
99	                'integration_id' => $this->integrationId,
100	                'error' => $e->getMessage(),
101	            ]);
102	
103	            throw $e;
104	        }
105	
106	        // Download logos and persist via BrandDesignMediaService — the same
107	        // service the dashboard upload path uses. Failures are non-fatal:
108	        // a missing logo just means the existing site_media row stays intact.
109	        $this->persistLogoFromShopify(
110	            $brandDesign,
111	            $site,
112	            (string) $integration->professional_id,
113	            'full',
114	            is_string($imported['logo']['full_url'] ?? null) ? $imported['logo']['full_url'] : null,
115	        );
116	        $this->persistLogoFromShopify(
117	            $brandDesign,
118	            $site,
119	            (string) $integration->professional_id,
120	            'square',
121	            is_string($imported['logo']['square_url'] ?? null) ? $imported['logo']['square_url'] : null,
122	        );
123	
124	        // Merge non-media design tokens into site.settings.design with
125	        // leave-if-absent semantics. Logo is intentionally NOT in this merge —
126	        // it lives in site_media now.
127	        $settings = is_array($site->settings) ? $site->settings : [];
128	        $design = is_array($settings['design'] ?? null) ? $settings['design'] : [];
129	        $existingColors = is_array($design['colors'] ?? null) ? $design['colors'] : [];
130	
131	        // Only accent stays brand-pickable. Background/text/border are derived
132	        // from theme_mode (light|dark) per Sidest theme.
133	        $design['colors'] = [
134	            'accent' => $imported['colors']['accent'] ?? ($existingColors['accent'] ?? null),
135	        ];
136	        $design['theme_mode'] = $imported['theme_mode'] ?? ($design['theme_mode'] ?? null);
137	        $design['corner_radius'] = $imported['corner_radius'] ?? ($design['corner_radius'] ?? null);
138	        $design['border_thickness'] = $imported['border_thickness'] ?? ($design['border_thickness'] ?? null);
139	        $design['section_spacing'] = $imported['section_spacing'] ?? ($design['section_spacing'] ?? null);
140	        $design['slogan'] = $imported['slogan'] ?? ($design['slogan'] ?? null);
141	
142	        // Strip the legacy logo subtree if any older row still has it. The
143	        // backfill migration cleans existing rows; this keeps us idempotent
144	        // for any row that gets re-synced before the migration runs.
145	        unset($design['logo']);
146	
147	        $settings['design'] = $design;
148	        $site->settings = $settings;
149	        $site->save();
150	
151	        // Mirror the shape to a shop metafield. Best-effort — a failure here
152	        // doesn't invalidate the DB write.
153	        if (! empty($imported['shop_gid'])) {
154	            try {
155	                $this->writeBrandDesignMetafield($integration, (string) $imported['shop_gid'], [
156	                    'colors' => $design['colors'],
157	                    'theme_mode' => $design['theme_mode'],
158	                    'corner_radius' => $design['corner_radius'],
159	                    'border_thickness' => $design['border_thickness'],
160	                    'section_spacing' => $design['section_spacing'],
161	                    'slogan' => $design['slogan'],
162	                    'synced_at' => now()->toIso8601String(),
163	                ]);
164	            } catch (\Throwable $e) {
165	                Log::warning('Failed to write sidest.brand_design metafield.', [
166	                    'integration_id' => $this->integrationId,
167	                    'error' => $e->getMessage(),
168	                ]);
169	            }
170	        }
171	
172	        // Bust the Hydrogen brand-design cache. The logo uploads above already
173	        // busted via BrandDesignMediaService::invalidateSiteCache, but the
174	        // site.settings.design writes (colors / enums / slogan) don't route
175	        // through that service, so this catches them.
176	        app(SiteCacheService::class)->forgetBrandDesign((string) $site->id);
177	
178	        Log::info('Brand design synced.', [
179	            'integration_id' => $this->integrationId,
180	            'professional_id' => (string) $integration->professional_id,
181	        ]);
182	    }
183	
184	    public function failed(\Throwable $e): void
185	    {
186	        Log::error('Shopify brand design sync permanently failed.', [
187	            'integration_id' => $this->integrationId,
188	            'error' => $e->getMessage(),
189	        ]);
190	    }
191	
192	    /**
193	     * Download the logo bytes from Shopify CDN and hand them to
194	     * BrandDesignMediaService for persistence + variant generation. A null
195	     * sourceUrl or any HTTP failure is silently ignored — the existing
196	     * site_media row (if any) stays intact.
197	     */
198	    private function persistLogoFromShopify(
199	        BrandDesignMediaService $brandDesign,
200	        Site $site,
201	        string $professionalId,
202	        string $variant,
203	        ?string $sourceUrl,
204	    ): void {
205	        if (! is_string($sourceUrl) || $sourceUrl === '' || ! str_starts_with($sourceUrl, 'https://')) {
206	            return;
207	        }
208	
209	        try {
210	            $response = Http::timeout(20)
211	                ->withOptions(['allow_redirects' => ['max' => 3, 'protocols' => ['https']]])
212	                ->get($sourceUrl);
213	
214	            if (! $response->ok()) {
215	                return;
216	            }
217	
218	            $bytes = $response->body();
219	            if ($bytes === '') {
220	                return;
221	            }
222	
223	            $mime = (string) $response->header('Content-Type') ?: 'image/png';
224	
225	            $brandDesign->upsertLogoFromBytes($site, $professionalId, $bytes, $mime, $variant);
226	        } catch (\Throwable $e) {
227	            Log::warning('Failed to persist Shopify-mirrored brand logo.', [
228	                'integration_id' => $this->integrationId,
229	                'variant' => $variant,
230	                'error' => $e->getMessage(),
231	            ]);
232	        }
233	    }
234	
235	    private function writeBrandDesignMetafield(ProfessionalIntegration $integration, string $shopGid, array $value): void
236	    {
237	        $metadata = is_array($integration->provider_metadata) ? $integration->provider_metadata : [];
238	        $shopDomain = trim((string) Arr::get($metadata, 'shop_domain', ''));
239	        $accessToken = trim((string) $integration->access_token);
240	        $apiVersion = trim((string) config('services.shopify.api_version', '2025-01'));
241	
242	        if ($shopDomain === '' || $accessToken === '') {
243	            return;
244	        }
245	
246	        $encoded = json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
247	        if ($encoded === false) {
248	            throw new \RuntimeException('Failed to encode brand design for metafield.');
249	        }
250	
251	        $response = app(\App\Services\Shopify\Client\ShopifyAdminClient::class)->graphql(
252	            $shopDomain,
253	            $accessToken,
254	            $apiVersion,
255	            self::METAFIELDS_SET_MUTATION,
256	            [
257	                'metafields' => [[
258	                    'namespace' => 'sidest',
259	                    'key' => 'brand_design',
260	                    'ownerId' => $shopGid,
261	                    'type' => 'json',
262	                    'value' => $encoded,
263	                ]],
264	            ],
265	        );
266	
267	        $userErrors = $response->json('data.metafieldsSet.userErrors', []);
268	        if (is_array($userErrors) && $userErrors !== []) {
269	            $message = (string) Arr::get($userErrors, '0.message', 'Shopify metafieldsSet returned errors.');
270	            throw new \RuntimeException($message);
271	        }
272	    }
273	}
