463	    /**
464	     * Resolve a merchant-facing Shopify domain (custom primary domain or
465	     * raw handle) to the canonical `<handle>.myshopify.com` used by the
466	     * OAuth authorize flow.
467	     *
468	     *   mystore                     -> mystore.myshopify.com            (rewrite-only)
469	     *   mystore.myshopify.com       -> mystore.myshopify.com            (rewrite-only)
470	     *   https://mystore/admin       -> mystore.myshopify.com            (rewrite-only)
471	     *   radiorufus.com              -> <handle>.myshopify.com           (HTML discovery)
472	     *
473	     * The discovery path fetches the storefront HTML and matches a Shopify
474	     * storefront global that embeds the canonical shop URL. Most non-headless
475	     * Shopify themes still expose this — Hydrogen storefronts and heavily
476	     * stripped themes won't, so the caller must surface a clear fallback
477	     * error when we return null.
478	     *
479	     * Auth-gated (brand professionals + staff) because it lets us make
480	     * arbitrary outbound HTTP requests on behalf of the caller — an abuse
481	     * vector if left open.
482	     */
483	    public function resolveShop(Request $request): JsonResponse
484	    {
485	        $validator = Validator::make($request->query(), [
486	            'domain' => ['required', 'string', 'max:255'],
487	        ]);
488	
489	        if ($validator->fails()) {
490	            throw new ValidationException($validator);
491	        }
492	
493	        $raw = (string) $validator->validated()['domain'];
494	        $host = $this->stripDomainNoise($raw);
495	
496	        if ($host === '') {
497	            return $this->error('Enter a valid Shopify store domain.', 422);
498	        }
499	
500	        // Already a myshopify handle — no discovery needed.
501	        if (preg_match('/^([a-z0-9][a-z0-9-]*)\.myshopify\.com$/', $host, $m)) {
502	            return $this->success(['shop_domain' => "{$m[1]}.myshopify.com"]);
503	        }
504	
505	        // Bare handle (no dots) — assume the caller typed the myshopify handle
506	        // without the TLD and rewrite. This matches the frontend's shortcut UX.
507	        if (preg_match('/^[a-z0-9][a-z0-9-]*$/', $host)) {
508	            return $this->success(['shop_domain' => "{$host}.myshopify.com"]);
509	        }
510	
511	        // Anything else is a potential custom storefront domain — try to
512	        // discover the myshopify handle by scraping the homepage HTML.
513	        $discovered = $this->discoverShopifyHandle($host);
514	
515	        if ($discovered === null) {
516	            return $this->error(
517	                "Couldn't find a Shopify store at {$host}. Enter your myshopify.com URL instead (Shopify admin → Settings → Domains).",
518	                404
519	            );
520	        }
521	
522	        return $this->success(['shop_domain' => $discovered]);
523	    }
