525	    /**
526	     * Strip scheme, path, querystring, port, and lowercase — leaves just
527	     * the hostname. Returns '' when the input can't be coerced into a host.
528	     *
529	     * Implemented with explicit strpos calls instead of a single regex
530	     * because including `#` inside a `#`-delimited character class trips
531	     * PHP's PCRE parser ("Unknown modifier ']'"), and Laravel escalates
532	     * that warning to a 500. Plain string ops sidestep the ambiguity.
533	     */
534	    private function stripDomainNoise(string $raw): string
535	    {
536	        $host = strtolower(trim($raw));
537	        if ($host === '') {
538	            return '';
539	        }
540	
541	        // Strip scheme.
542	        if (str_starts_with($host, 'https://')) {
543	            $host = substr($host, 8);
544	        } elseif (str_starts_with($host, 'http://')) {
545	            $host = substr($host, 7);
546	        }
547	
548	        // Cut at the first boundary character — path, port, query, fragment.
549	        foreach ([':', '/', '?', '#'] as $boundary) {
550	            $pos = strpos($host, $boundary);
551	            if ($pos !== false) {
552	                $host = substr($host, 0, $pos);
553	            }
554	        }
555	
556	        return $host;
557	    }
