42	    private function currentShopifyIntegrationForBrand(string $brandProfessionalId): ?ProfessionalIntegration
43	    {
44	        return ProfessionalIntegration::query()
45	            ->where('professional_id', $brandProfessionalId)
46	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
