50	    /**
51	     * @return array{0: string, 1: JsonResponse|null}
52	     *
53	     * @throws AuthorizationException (403 or 423) — callers let it propagate.
54	     */
55	    private function resolveTargetBrandProfessionalId(
56	        Request $request,
57	        ?string $requestedBrandProfessionalId,
58	        bool $requireForNonBrand,
59	        string $ability = 'manage'
60	    ): array {
61	        $professional = $this->currentProfessional($request);
62	        $requestedBrandProfessionalId = trim((string) $requestedBrandProfessionalId);
63	
64	        if ($requestedBrandProfessionalId === '') {
65	            if ($this->brandAccess->isBrandProfessional($professional)) {
66	                $requestedBrandProfessionalId = (string) $professional->id;
67	            } elseif ($requireForNonBrand) {
68	                return ['', $this->error('brand_professional_id is required for this account type.', 422)];
69	            } else {
70	                return ['', null];
71	            }
72	        }
73	
74	        $skeleton = new ProfessionalIntegration([
75	            'professional_id' => $requestedBrandProfessionalId,
76	            'provider' => ProfessionalIntegration::PROVIDER_SHOPIFY,
77	        ]);
78	
79	        // Throws AuthorizationException (403 or 423) — callers let it propagate.
80	        $this->authorizeForUser($professional, $ability, $skeleton);
81	
82	        return [$requestedBrandProfessionalId, null];
83	    }
