95	    {
96	        $validator = Validator::make($request->query(), [
97	            'brand_professional_id' => ['sometimes', 'uuid'],
98	        ]);
99	
100	        if ($validator->fails()) {
101	            throw new ValidationException($validator);
102	        }
103	
104	        [$targetBrandId, $error] = $this->resolveTargetBrandProfessionalId(
105	            $request,
106	            isset($validator->validated()['brand_professional_id']) ? (string) $validator->validated()['brand_professional_id'] : null,
107	            false,
108	            'view'
109	        );
110	
111	        if ($error !== null) {
112	            return $error;
113	        }
114	
115	        if ($targetBrandId === '') {
116	            return $this->success([
117	                'eligible' => false,
118	                'connected' => false,
