157	    public function connect(Request $request): JsonResponse
158	    {
159	        $validator = Validator::make($request->all(), [
160	            'brand_professional_id' => ['sometimes', 'uuid'],
161	            'shop_domain' => ['required', 'string', 'max:255'],
162	            'access_token' => ['required', 'string'],
163	            'refresh_token' => ['sometimes', 'nullable', 'string'],
164	            'expires_at' => ['sometimes', 'nullable', 'date'],
165	            'shop_id' => ['sometimes', 'nullable', 'string', 'max:255'],
166	            'scopes' => ['sometimes', 'array'],
167	            'scopes.*' => ['string', 'max:120'],
168	            'webhook_orders_topic' => ['sometimes', 'nullable', 'string', 'max:120'],
169	            'shop_data' => ['sometimes', 'nullable', 'array'],
170	        ]);
171	
172	        if ($validator->fails()) {
173	            throw new ValidationException($validator);
174	        }
175	
176	        $validated = $validator->validated();
177	
178	        [$targetBrandId, $error] = $this->resolveTargetBrandProfessionalId(
179	            $request,
180	            isset($validated['brand_professional_id']) ? (string) $validated['brand_professional_id'] : null,
181	            true
182	        );
183	
184	        if ($error !== null) {
185	            return $error;
186	        }
187	
188	        $shopDomain = $this->normalizeShopDomain((string) ($validated['shop_domain'] ?? ''));
189	        if ($shopDomain === '') {
190	            return $this->error('shop_domain is required.', 422);
191	        }
192	
193	        $actorProfessional = $this->currentProfessional($request);
194	
195	        $conflictingIntegration = ProfessionalIntegration::query()
196	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
197	            ->where('professional_id', '!=', $targetBrandId)
198	            ->where('shopify_shop_domain', $shopDomain)
199	            ->exists();
200	
201	        if ($conflictingIntegration) {
202	            return $this->error('This Shopify shop domain is already connected to another brand.', 409);
203	        }
204	
205	        $existing = $this->currentShopifyIntegrationForBrand($targetBrandId);
206	        $existingMetadata = is_array($existing?->provider_metadata) ? $existing->provider_metadata : [];
207	
208	        $metadata = array_merge($existingMetadata, [
209	            'shop_domain' => $shopDomain,
210	            'shop_id' => isset($validated['shop_id']) ? trim((string) $validated['shop_id']) : Arr::get($existingMetadata, 'shop_id'),
211	            'scopes' => array_values(array_unique(array_filter(array_map(
212	                static fn ($scope): string => trim((string) $scope),
213	                Arr::wrap($validated['scopes'] ?? Arr::get($existingMetadata, 'scopes', []))
214	            ), static fn (string $scope): bool => $scope !== ''))),
215	            'webhook_orders_topic' => trim((string) ($validated['webhook_orders_topic'] ?? Arr::get(
216	                $existingMetadata,
217	                'webhook_orders_topic',
218	                config('services.shopify.webhook_orders_topic', 'orders/paid')
219	            ))),
220	            'connected_at' => now()->toIso8601String(),
221	            'webhook_registration_state' => 'queued',
222	        ]);
223	
224	        $integration = ProfessionalIntegration::query()->updateOrCreate(
225	            [
226	                'professional_id' => $targetBrandId,
227	                'provider' => ProfessionalIntegration::PROVIDER_SHOPIFY,
228	            ],
229	            [
230	                'external_account_id' => $shopDomain,
231	                'access_token' => (string) $validated['access_token'],
232	                'refresh_token' => isset($validated['refresh_token'])
233	                    ? (string) $validated['refresh_token']
234	                    : ($existing?->refresh_token),
235	                'expires_at' => $validated['expires_at'] ?? null,
236	                'last_catalog_sync_error' => null,
237	                'provider_metadata' => $metadata,
238	            ]
239	        );
240	
241	        // Ensure BrandProfile exists (covers manual-signup brands connecting Shopify later)
242	        BrandProfile::firstOrCreate(
243	            ['professional_id' => $targetBrandId],
244	            ['setup_complete' => false]
245	        );
246	
247	        // Auto-fill empty profile fields from Shopify shop data (manual-signup → Shopify connect)
248	        $shopData = $validated['shop_data'] ?? null;
249	        if (is_array($shopData) && $shopData !== []) {
250	            $professional = Professional::find($targetBrandId);
251	            $site = Site::where('professional_id', $targetBrandId)->first();
252	            $brandProfile = BrandProfile::where('professional_id', $targetBrandId)->first();
253	
254	            if ($professional && $site) {
255	                app(ShopProfileAutoFillService::class)->fillFromShopData($professional, $site, $brandProfile, $shopData, $integration);
256	            }
257	        }
258	
259	        $webhookRegistrationQueued = true;
260	        $jobs = [
261	            RegisterShopifyWebhooksJob::class,
262	            CreateStorefrontAccessTokenJob::class,
263	            CreateShopifyMetafieldsJob::class, // chains → CreateShopifyCollectionsJob
264	            CreateShopifySalesChannelJob::class,
265	            // Unified brand-design sync: logos, colours, enums, slogan in one job.
266	            SyncShopifyBrandDesignJob::class,
267	        ];
268	
269	        foreach ($jobs as $jobClass) {
270	            try {
271	                $jobClass::dispatch((string) $integration->id);
272	            } catch (\Throwable $e) {
273	                $webhookRegistrationQueued = false;
274	                Log::warning('Failed to dispatch Shopify install job', [
275	                    'actor_professional_id' => (string) $actorProfessional->id,
276	                    'brand_professional_id' => $targetBrandId,
277	                    'integration_id' => (string) $integration->id,
278	                    'job' => class_basename($jobClass),
279	                    'message' => $e->getMessage(),
280	                ]);
281	            }
282	        }
283	
284	        return $this->success([
285	            'connected' => true,
286	            'brand_professional_id' => $targetBrandId,
287	            'shop_domain' => $shopDomain,
288	            'shop_id' => Arr::get($metadata, 'shop_id'),
289	            'expires_at' => $integration->expires_at?->toIso8601String(),
290	            'webhook_registration_queued' => $webhookRegistrationQueued,
291	        ]);
292	    }
293	
294	    /**
295	     * Disconnect the brand's Shopify integration with a full server-side
296	     * sweep. Unlike a Shopify-initiated uninstall (where the token is
297	     * revoked BEFORE we hear about it), this runs while we still hold a
298	     * valid token, so we can delete:
299	     *   - The Side St Price automatic discount
300	     *   - The four Side St collections
301	     *   - Every sidest.* metafield definition (with values)
302	     *   - The Side St storefront access token
303	     *   - The Side St sales channel publication
304	     *   - Revoke the OAuth token itself
305	     *
306	     * Then locally:
307	     *   - Purge affiliate_product_selections scoped to this brand (any
308	     *     affiliate-curated lists become meaningless once the catalog is
309	     *     gone)
310	     *   - Delete the ProfessionalIntegration row
311	     *
312	     * Safe to call when no integration exists (returns success with an
313	     * empty teardown summary). Per-step failures in the Shopify sweep are
314	     * logged but don't abort the local cleanup — a brand who's already
315	     * uninstalled in Shopify still gets their local state cleared cleanly.
316	     */
317	    public function disconnect(Request $request): JsonResponse
318	    {
319	        $validator = Validator::make($request->all(), [
320	            'brand_professional_id' => ['sometimes', 'uuid'],
321	        ]);
322	
323	        if ($validator->fails()) {
324	            throw new ValidationException($validator);
325	        }
326	
327	        [$targetBrandId, $error] = $this->resolveTargetBrandProfessionalId(
328	            $request,
329	            isset($validator->validated()['brand_professional_id']) ? (string) $validator->validated()['brand_professional_id'] : null,
330	            true
331	        );
332	
333	        if ($error !== null) {
334	            return $error;
335	        }
336	
337	        $actorProfessional = $this->currentProfessional($request);
338	
339	        $integration = $this->currentShopifyIntegrationForBrand($targetBrandId);
340	
341	        $teardownSummary = null;
342	        if ($integration && ! empty($integration->access_token)) {
343	            try {
344	                $teardownSummary = $this->teardownService->teardownForIntegration($integration);
345	            } catch (\Throwable $e) {
346	                // The teardown service already logs per-step failures; this
347	                // catch only fires on a truly unexpected exception. We keep
348	                // going so the local disconnect still runs — leaving the
349	                // brand half-disconnected (Shopify side still present but
350	                // Side St thinks it's gone) is worse than orphaning a few
351	                // Shopify-side artifacts we can't re-reach.
352	                Log::error('Shopify teardown threw unexpectedly; continuing with local disconnect', [
353	                    'actor_professional_id' => (string) $actorProfessional->id,
354	                    'brand_professional_id' => $targetBrandId,
355	                    'error' => $e->getMessage(),
356	                ]);
357	            }
358	        }
359	
360	        // Affiliate curated selections only make sense while this brand has
361	        // a catalog to curate from. Blow them away so the affiliates don't
362	        // end up with dangling GIDs pointing at deleted products.
363	        $deletedSelections = AffiliateProductSelection::query()
364	            ->where('brand_professional_id', $targetBrandId)
365	            ->delete();
366	
367	        ProfessionalIntegration::query()
368	            ->where('professional_id', $targetBrandId)
369	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
370	            ->delete();
371	
372	        // Clear all wizard progress so the setup wizard starts fresh if the brand reconnects.
373	        BrandStoreSettings::clearWizardProgress($targetBrandId);
374	        BrandProfile::where('professional_id', $targetBrandId)
375	            ->update(['setup_complete' => false]);
376	
377	        Log::info('Shopify disconnected', [
378	            'actor_professional_id' => (string) $actorProfessional->id,
379	            'brand_professional_id' => $targetBrandId,
380	            'teardown_summary' => $teardownSummary,
381	            'deleted_selections' => $deletedSelections,
382	        ]);
383	
384	        return $this->success([
385	            'connected' => false,
386	            'brand_professional_id' => $targetBrandId,
387	            'teardown' => $teardownSummary,
388	            'selections_deleted' => $deletedSelections,
389	        ]);
390	    }
