429	    public function registerWebhooks(Request $request): JsonResponse
430	    {
431	        $validator = Validator::make($request->all(), [
432	            'brand_professional_id' => ['sometimes', 'uuid'],
433	        ]);
434	
435	        if ($validator->fails()) {
436	            throw new ValidationException($validator);
437	        }
438	
439	        [$targetBrandId, $error] = $this->resolveTargetBrandProfessionalId(
440	            $request,
441	            isset($validator->validated()['brand_professional_id']) ? (string) $validator->validated()['brand_professional_id'] : null,
442	            true
443	        );
