489	        if ($validator->fails()) {
490	            throw new ValidationException($validator);
491	        }
492	
493	        $raw = (string) $validator->validated()['domain'];
494	        $host = $this->stripDomainNoise($raw);
495	
496	        if ($host === '') {
497	            return $this->error('Enter a valid Shopify store domain.', 422);
498	        }
499	
500	        // Already a myshopify handle — no discovery needed.
501	        if (preg_match('/^([a-z0-9][a-z0-9-]*)\.myshopify\.com$/', $host, $m)) {
