503	        }
504	
505	        // Bare handle (no dots) — assume the caller typed the myshopify handle
506	        // without the TLD and rewrite. This matches the frontend's shortcut UX.
507	        if (preg_match('/^[a-z0-9][a-z0-9-]*$/', $host)) {
508	            return $this->success(['shop_domain' => "{$host}.myshopify.com"]);
509	        }
510	
511	        // Anything else is a potential custom storefront domain — try to
512	        // discover the myshopify handle by scraping the homepage HTML.
