559	    /**
560	     * Reject private / link-local / loopback / multicast / reserved addresses
561	     * before issuing an outbound HTTP request. Prevents the resolveShop endpoint
562	     * from being abused as an SSRF probe against internal infrastructure.
563	     *
564	     * Accepts a host (IP literal or hostname). For hostnames, resolves all A
565	     * records and rejects if any resolved IP falls in a blocked range.
566	     */
567	    private function isPrivateHost(string $host): bool
568	    {
569	        $host = trim($host);
570	        if ($host === '') {
571	            return true;
572	        }
573	
574	        // If $host is a literal IP, just check it.
575	        if (filter_var($host, FILTER_VALIDATE_IP)) {
576	            return $this->ipIsBlocked($host);
577	        }
578	
579	        // Otherwise resolve and check every A record.
580	        $ips = gethostbynamel($host);
581	        if ($ips === false || empty($ips)) {
582	            // Non-resolvable — let the caller's Http::get error path handle it.
583	            return false;
584	        }
585	
586	        foreach ($ips as $ip) {
587	            if ($this->ipIsBlocked($ip)) {
588	                return true;
589	            }
590	        }
591	
592	        return false;
593	    }
594	
595	    private function ipIsBlocked(string $ip): bool
596	    {
597	        // NO_PRIV_RANGE  blocks 10/8, 172.16/12, 192.168/16, fc00::/7, fec0::/10
598	        // NO_RES_RANGE   blocks 0/8, 127/8, 169.254/16, 224/4, 240/4, ::1, fe80::/10
599	        $notPrivate = filter_var(
600	            $ip,
601	            FILTER_VALIDATE_IP,
602	            FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE
603	        );
604	
605	        return $notPrivate === false;
606	    }
607	
608	    /**
609	     * Fetch the storefront homepage and look for the embedded
610	     * `Shopify.shop = "<handle>.myshopify.com"` global that most themes
611	     * render inline. Returns the canonical shop domain or null.
612	     *
613	     * Network / parse failures are swallowed and translated into null —
614	     * the caller turns that into a user-facing 404.
615	     */
616	    private function discoverShopifyHandle(string $host): ?string
617	    {
618	        // SSRF guard: an authenticated brand can still probe internal infrastructure
619	        // via this endpoint. Rejecting private/link-local/loopback IPs blocks
620	        // metadata endpoints (169.254.169.254) and internal services without
621	        // breaking legitimate custom Shopify domains.
622	        if ($this->isPrivateHost($host)) {
623	            Log::info('Shopify resolveShop: rejected private/internal host', ['host' => $host]);
624	
625	            return null;
626	        }
627	
628	        $url = "https://{$host}/";
629	
630	        try {
631	            $response = Http::timeout(6)
632	                ->connectTimeout(4)
633	                // SSRF hardening: disable redirects. Without this, a public-IP
634	                // storefront could 302 to an internal host (e.g. 169.254.169.254)
635	                // and Guzzle would follow it — bypassing isPrivateHost above.
636	                ->withOptions(['allow_redirects' => false])
637	                ->withHeaders([
638	                    // Some Shopify storefronts block default PHP/curl user agents
639	                    // with a WAF rule. A real-browser UA sidesteps that without
640	                    // misrepresenting intent.
641	                    'User-Agent' => 'Mozilla/5.0 (compatible; SidestShopResolver/1.0)',
642	                    'Accept' => 'text/html,application/xhtml+xml',
643	                ])
644	                ->get($url);
645	        } catch (ConnectionException $e) {
646	            Log::info('Shopify resolveShop: connection failed', [
647	                'host' => $host,
648	                'error' => $e->getMessage(),
649	            ]);
650	
651	            return null;
652	        } catch (\Throwable $e) {
653	            Log::info('Shopify resolveShop: unexpected error', [
654	                'host' => $host,
655	                'error' => $e->getMessage(),
656	            ]);
657	
658	            return null;
659	        }
660	
661	        if (! $response->successful()) {
662	            return null;
663	        }
664	
665	        $body = (string) $response->body();
666	
667	        // Shopify themes commonly embed one of these:
668	        //   Shopify.shop = "foo.myshopify.com"
669	        //   "shop":"foo.myshopify.com"
670	        //   shop: "foo.myshopify.com"
671	        // All carry the canonical <handle>.myshopify.com; we take the first.
672	        $patterns = [
673	            '/Shopify\.shop\s*=\s*["\']([a-z0-9][a-z0-9-]*\.myshopify\.com)["\']/i',
674	            '/["\']shop["\']\s*:\s*["\']([a-z0-9][a-z0-9-]*\.myshopify\.com)["\']/i',
675	            '/([a-z0-9][a-z0-9-]*\.myshopify\.com)/i',
676	        ];
677	
678	        foreach ($patterns as $pattern) {
679	            if (preg_match($pattern, $body, $m)) {
680	                return strtolower($m[1]);
681	            }
682	        }
683	
684	        return null;
685	    }
686	}
